<?php
declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_once dirname(__DIR__,2).'/includes/alert-engine.php';header('Content-Type: application/json; charset=utf-8');
function p4_alert_reply(int $s,array $b):never{http_response_code($s);echo json_encode($b,JSON_THROW_ON_ERROR);exit;}if(($_SERVER['REQUEST_METHOD']??'')!=='GET')p4_alert_reply(405,['success'=>false,'message'=>'Use GET.']);$u=current_user();if(!$u)p4_alert_reply(401,['success'=>false,'message'=>'Authentication required.']);if(!in_array($u['role_slug'],['administrator','environmental_staff'],true))p4_alert_reply(403,['success'=>false,'message'=>'Access denied.']);$rows=db()->query("SELECT al.id,al.alert_type,al.severity,al.sensor_value,al.status,al.first_triggered_at,al.last_triggered_at,e.business_name,g.name grease_trap,d.device_code FROM alerts al JOIN device_assignments a ON a.id=al.device_assignment_id JOIN devices d ON d.id=a.device_id JOIN grease_traps g ON g.id=a.grease_trap_id JOIN establishments e ON e.id=g.establishment_id ORDER BY (al.status='RESOLVED'),al.last_triggered_at DESC LIMIT 250")->fetchAll();p4_alert_reply(200,['success'=>true,'data'=>['alerts'=>$rows]]);
